def solve(grid):
    g=[row[:] for row in grid]; H=len(g); W=len(g[0])
    bg=Counter(v for row in g for v in row).most_common(1)[0][0]
    sp=lambda v: v!=bg
    counts=[sum(1 for v in row if sp(v)) for row in g]
    is_band=[counts[r]>=0.25*W for r in range(H)]
    bands=[]; r=0
    while r<H:
        if is_band[r]:
            r0=r
            while r<H and is_band[r]: r+=1
            bands.append((r0,r-1))
        else: r+=1
    def rowext(row): return max((c for c,v in enumerate(row) if sp(v)),default=-1)
    bext=[max(rowext(g[r_]) for r_ in range(a,b+1)) for a,b in bands]
    gmax=max(bext)
    flags=set()
    # rule C: pair corresponding rows of consecutive bands; trailing = beyond min of band maxexts
    for bi,((a0,a1),(b0,b1)) in enumerate(zip(bands,bands[1:])):
        for k in range(min(a1-a0+1,b1-b0+1)):
            ra,rb=a0+k,b0+k
            tgt=rb if counts[rb]<=counts[ra] else ra   # poorer row; tie -> bottom
            src=ra if tgt==rb else rb
            for c in range(min(bext[bi],bext[bi+1])+1,W):
                if g[tgt][c]!=g[src][c]: flags.add((tgt,c))
    # completion rule: non-first band rows: bg cells beyond global band extent -> 1
    for bi,(a,b) in enumerate(bands):
        if bi==0: continue
        for r_ in range(a,b+1):
            for c in range(gmax+1,W):
                if g[r_][c]==bg: flags.add((r_,c))
    for (r_,c) in flags: g[r_][c]=1
    return g

